import math
def read(fn):
    L=open(fn).read().splitlines(); n=int(L[0]); at=[]
    for l in L[2:2+n]:
        s=l.split(); at.append((s[0],float(s[1]),float(s[2]),float(s[3])))
    return at
for fn in ['opt.xyz','opt_trans.xyz','opt2.xyz']:
    at=read(fn)
    def v(i): return at[i][1:]
    def sub(a,b): return (a[0]-b[0],a[1]-b[1],a[2]-b[2])
    def dot(a,b): return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]
    def norm(a): return math.sqrt(dot(a,a))
    def angle(i,j,k):
        a=sub(v(i),v(j)); c=sub(v(k),v(j))
        return math.degrees(math.acos(max(-1,min(1,dot(a,c)/(norm(a)*norm(c))))))
    W=v(0)
    donors={'Cco':1,'Nmp':3,'N0':9,'Nb':17,'Nd':29,'Oa':20,'Ob':32}
    ds={k:round(math.dist(v(i),W),3) for k,i in donors.items()}
    print(fn,"Cco-W-Nmp=",round(angle(1,0,3),1)," W-C,O(co):",round(math.dist(v(1),W),2),round(math.dist(v(1),v(2)),2)," donors:",ds)
